def _group_type_label(family: FamilyGroup) -> str:
    group_type = getattr(getattr(family, "group_type", None), "type", None)
    if group_type == "META":
        return "Network"
    if getattr(family, "group_type", None):
        return family.group_type.get_type_display()
    return "Group"


def _membership_role_label(membership: FamilyMembership) -> str:
    if getattr(membership, "is_virtual", False):
        return membership.role

    if hasattr(membership, "get_role_display"):
        return membership.get_role_display()

    return str(membership.role).replace("_", " ").title()


def _classify_membership(
    membership: FamilyMembership, primary_family: FamilyGroup | None
) -> str:
    if primary_family and membership.family_id == primary_family.id:
        return "home"
    if getattr(membership, "is_virtual", False):
        return "connected"
    if membership.is_admin:
        return "managed"
    return "direct"


