                    ),
                )
            )
            seen_family_ids.add(cfm.family_id)

    # Add meta families (networks) themselves if not already present
    all_meta_families = FamilyGroup.objects.filter(
        id__in=network.meta_family_ids
    ).select_related("group_type")
    for mf in all_meta_families:
        if mf.id not in seen_family_ids:
            member_count = network_member_counts.get(str(mf.id), 0)
            membership_count_label = (
                f"{member_count} connected families"
                if member_count != 1
                else "1 connected family"
            )
            memberships.append(
                VirtualMembership(
                    mf,
                    role="Network",
                    connection_labels=[membership_count_label],
                )
            )
            seen_family_ids.add(mf.id)

