    admin_memberships = get_user_admin_memberships(user)

    # Get pending invites for families where user is admin
    admin_family_ids = list(admin_memberships.values_list("family_id", flat=True))
    pending_invites = FamilyInvite.objects.filter(
        family_id__in=admin_family_ids, status="PENDING"
    )

    # Get invites sent to the user's email
    user_invites = FamilyInvite.objects.filter(email=user.email, status="PENDING")

    pending_network_received = PendingMetaFamilyMembership.objects.filter(
