    pending_requests = FamilyJoinRequest.objects.filter(user=user, status="PENDING")

    # Get pending join requests for families where user is admin
    pending_join_requests = FamilyJoinRequest.objects.filter(
        family_id__in=admin_family_ids, status="PENDING"
