        if not hasattr(membership, "connection_labels"):
            membership.connection_labels = connection_labels_by_family.get(
                str(membership.family_id), []
            )

        membership.section_id = section_id
        membership.type_label = _group_type_label(family)
        membership.role_label = _membership_role_label(membership)
        membership.reason_label = _reason_label(section_id)
        membership.can_manage = membership.is_admin and not getattr(
