            DIRECTORY_SECTION_ORDER.index(membership.section_id),
            membership.family.name.lower(),
        )
    )

    for section_id in DIRECTORY_SECTION_ORDER:
        section_items = [
            membership for membership in memberships if membership.section_id == section_id
        ]
        if not section_items:
            continue

        section_config = DIRECTORY_SECTION_CONFIG[section_id]
        group_sections.append(
            {
                "id": section_id,
                "title": section_config["title"],
                "description": section_config["description"],
                "default_open": section_config["default_open"],
                "is_collapsible": section_config["is_collapsible"],
                "items": section_items,
            }
        )

