        "all": len(memberships),
        "managed": len(
            [membership for membership in memberships if membership.section_id == "managed"]
        ),
        "direct": len(
            [membership for membership in memberships if membership.section_id == "direct"]
        ),
        "connected": len(
            [
                membership
                for membership in memberships
